import{G as e,b as t,c as r,ae as o}from"./chunks/framework.l_MR1ur9.js";const A=JSON.parse('{"title":"AI和AIGC","description":"","frontmatter":{"title":"AI和AIGC","date":"2023-11-22 00:31:52","author":"花木凋零成兰","tags":["AI","AIGC"],"categories":["人工智能"]},"headers":[],"relativePath":"AI/AI和AIGC.md","filePath":"AI/AI和AIGC.md","lastUpdated":1791630580000}'),i={name:"AI/AI和AIGC.md"};function n(l,a,h,d,s,c){return t(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1700613112000"},[...a[0]||(a[0]=[o('<h1 id="ai和aigc" tabindex="-1">AI和AIGC <a class="header-anchor" href="#ai和aigc" aria-label="Permalink to &quot;AI和AIGC&quot;">​</a></h1><h2 id="ai-的定义" tabindex="-1">AI 的定义 <a class="header-anchor" href="#ai-的定义" aria-label="Permalink to &quot;AI 的定义&quot;">​</a></h2><p>AI，英文名称为：Artificial Intelligence，即<strong>人工智能</strong>。</p><p>AI的核心定义；由人制造出来的智能，让机器像人一样思考和行动，例如学习、推理、解决问题等。</p><h2 id="ai-的分类" tabindex="-1">AI 的分类 <a class="header-anchor" href="#ai-的分类" aria-label="Permalink to &quot;AI 的分类&quot;">​</a></h2><p>人工智能大致可以分为两类：</p><ul><li><p>窄人工智能 (Narrow AI)</p></li><li><p>通用人工智能 (General AI)</p></li></ul><h2 id="窄人工智能" tabindex="-1">窄人工智能 <a class="header-anchor" href="#窄人工智能" aria-label="Permalink to &quot;窄人工智能&quot;">​</a></h2><p>也称为弱人工智能，是目前最常见的AI类型。 主要用于在特定领域或任务中，且不懂该领域之外的任务。比如语音识别软件只擅长处理语音，而不懂其他任务。 这些系统通常基于<strong>大数据的学习</strong>和<strong>模式识别</strong>。</p><h2 id="通用人工智能" tabindex="-1">通用人工智能 <a class="header-anchor" href="#通用人工智能" aria-label="Permalink to &quot;通用人工智能&quot;">​</a></h2><p>也称为最强人工智能，是一种理论上的AI，可以像人类一样执行任何智能任务，目前还未实现。</p><h2 id="其他子领域" tabindex="-1">其他子领域 <a class="header-anchor" href="#其他子领域" aria-label="Permalink to &quot;其他子领域&quot;">​</a></h2><h3 id="机器学习" tabindex="-1">机器学习 <a class="header-anchor" href="#机器学习" aria-label="Permalink to &quot;机器学习&quot;">​</a></h3><p>是AI的一个分支，能让机器从数据中学习，而不是完全依靠预设的规则</p><h3 id="深度学习" tabindex="-1">深度学习 <a class="header-anchor" href="#深度学习" aria-label="Permalink to &quot;深度学习&quot;">​</a></h3><p>是机器学习的子集，通过模拟人脑的神经网络结构来学习数据。</p><h3 id="自然语言处理-nlp" tabindex="-1">自然语言处理(NLP) <a class="header-anchor" href="#自然语言处理-nlp" aria-label="Permalink to &quot;自然语言处理(NLP)&quot;">​</a></h3><p>是AI在语言理解和生成方面的应用。</p><h2 id="aigc" tabindex="-1">AIGC <a class="header-anchor" href="#aigc" aria-label="Permalink to &quot;AIGC&quot;">​</a></h2><p>AIGC 是AI的一个重要分支，全程是 <strong>AI generated content</strong>，在国内被称为生成式AI；即指利用人工智能技术自动生成各种类型的内容。</p><h2 id="主要应用领域" tabindex="-1">主要应用领域 <a class="header-anchor" href="#主要应用领域" aria-label="Permalink to &quot;主要应用领域&quot;">​</a></h2><h3 id="文本生成" tabindex="-1">文本生成 <a class="header-anchor" href="#文本生成" aria-label="Permalink to &quot;文本生成&quot;">​</a></h3><p>利用AIGC生成连贯、自然的文本内容，如：谷歌的Bard、百度的文心一言等</p><h3 id="图像生成" tabindex="-1">图像生成 <a class="header-anchor" href="#图像生成" aria-label="Permalink to &quot;图像生成&quot;">​</a></h3><p>利用AIGC生成逼真的图像</p><h3 id="视频生成" tabindex="-1">视频生成 <a class="header-anchor" href="#视频生成" aria-label="Permalink to &quot;视频生成&quot;">​</a></h3><p>合成和编辑视频，生成具有特定场景、角色和动作的视频片段，如日本流行的虚拟偶像初音未来。</p><h2 id="其他应用领域" tabindex="-1">其他应用领域 <a class="header-anchor" href="#其他应用领域" aria-label="Permalink to &quot;其他应用领域&quot;">​</a></h2><p>如音频合成、数据可视化、自动编程等。</p><h2 id="参考学习资料" tabindex="-1">参考学习资料 <a class="header-anchor" href="#参考学习资料" aria-label="Permalink to &quot;参考学习资料&quot;">​</a></h2><p><a href="https://xiaobot.net/p/ai666" target="_blank" rel="noreferrer">每个人的AI学习手册 (xiaobot.net)</a></p><p><a href="https://xiaobot.net/post/01cf1168-2481-4a35-a3cc-50cd38aa785a" target="_blank" rel="noreferrer">第01讲：什么是AI？ (xiaobot.net)</a></p><p><a href="https://xiaobot.net/post/32e5ec35-fade-43b7-92ef-45f10aafc1d3" target="_blank" rel="noreferrer">第02讲：什么是AIGC？ (xiaobot.net)</a></p>',33)])])}const I=e(i,[["render",n]]);export{A as __pageData,I as default};
